<?php $pageTitle='Match Center';require_once __DIR__.'/includes/header.php';$t=active_tournament($pdo);$status=$_GET['status']??'all';$allowed=['all','live','scheduled','finished'];if(!in_array($status,$allowed,true))$status='all';$sql="SELECT m.*,p1.name p1_name,p2.name p2_name FROM matches m LEFT JOIN participants p1 ON p1.id=m.participant1_id LEFT JOIN participants p2 ON p2.id=m.participant2_id WHERE m.tournament_id=?";$params=[$t['id']??0];if($status!=='all'){$sql.=' AND m.status=?';$params[]=$status;}$sql.=' ORDER BY m.round_number,m.match_number';$s=$pdo->prepare($sql);$s->execute($params);?>
<main><section class="page-hero"><div class="container"><div class="eyebrow">Fixtures & results</div><h1>Match center</h1><div class="tabs"><?php foreach(['all'=>'All','live'=>'Live','scheduled'=>'Upcoming','finished'=>'Finished'] as $key=>$label):?><a class="tab <?=$status===$key?'active':''?>" href="?status=<?=$key?>"><?=$label?></a><?php endforeach;?></div></div></section><section class="section"><div class="container"><div class="grid grid-3"><?php $rows=$s->fetchAll();if(!$rows):?><div class="card empty"><i class="fa-regular fa-calendar-xmark"></i><p>No matches in this category.</p></div><?php endif;foreach($rows as $m):?><a class="card match-card" href="match.php?id=<?=$m['id']?>"><div class="match-card-head"><span class="round-label"><?=e($m['round'])?> · #<?=$m['id']?></span><span class="badge <?=e($m['status'])?>"><?=e($m['status'])?></span></div><div class="team-line"><span class="team"><span class="team-logo"><?=strtoupper(substr($m['p1_name']??'T',0,1))?></span><?=e($m['p1_name']??'TBD')?></span><span class="score"><?=$m['score1']?></span></div><div class="team-line"><span class="team"><span class="team-logo"><?=strtoupper(substr($m['p2_name']??'T',0,1))?></span><?=e($m['p2_name']??'TBD')?></span><span class="score"><?=$m['score2']?></span></div><div class="match-card-foot"><span><?=e($m['court']??'TBA')?></span><span><?=$m['scheduled_at']?date('d M · H:i',strtotime($m['scheduled_at'])):'Schedule TBA'?></span></div></a><?php endforeach;?></div></div></section></main>
<?php require __DIR__.'/includes/footer.php';?>

